// Service worker for the Takamul site (generated by tools/build.py — edit tools/sw.template.js).
// HTML: network-first (fresh content when online, cached copy offline).
// CSS/JS with ?v=<hash>: cache-first (immutable). Other assets: network-first. /api/* is never cached.
const VERSION = '__VERSION__';
const CACHE = 'takamul-' + VERSION;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('takamul-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || url.pathname.startsWith('/api/')) return;
  const isPage = req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html');
  if (isPage) {
    e.respondWith(fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return res;
    }).catch(() => caches.match(req, { ignoreSearch: true })
      .then(r => r || caches.match(url.pathname.replace(/[^/]*$/, '') + 'index.html'))
      .then(r => r || caches.match('./index.html'))));
    return;
  }
  const versioned = url.searchParams.has('v');
  const fromNet = () => fetch(req).then(res => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  });
  // ?v=<hash> files never change → cache first; everything else → network first, cache offline
  e.respondWith(versioned
    ? caches.match(req).then(hit => hit || fromNet())
    : fromNet().catch(() => caches.match(req, { ignoreSearch: true })));
});
